}

challenges.solution:
function paginar(itens, pagina, tamanho) {
  const inicio = (pagina - 1) * tamanho
  // slice ja exclui o fim: somar 1 fazia a pagina ter tamanho + 1 item,
  // e o excedente era o primeiro item da pagina seguinte.
  return itens.slice(inicio, inicio + tamanho)
}

