}

challenges.solution:
function totalBate(calculado, informado) {
  // Decimal em binario quase nunca e exato: 0.1 + 0.2 da 0.30000000000000004.
  // Comparar com tolerancia e o unico jeito de a conferencia nao acusar
  // divergencia em valores que sao iguais na pratica.
  return Math.abs(calculado - informado) <= 0.01
}

