}

challenges.solution:
function maisRecentes(tickets) {
  // sort ordena NO LUGAR e devolve o mesmo array: quem chamou tem a ordem
  // trocada debaixo dele. Copiar antes isola a funcao de quem a usa.
  return [...tickets].sort((a, b) => (a.criadoEm < b.criadoEm ? 1 : -1))
}

function ranking(valores) {
  // sort() sem comparador converte para texto: '100' < '9' alfabeticamente.
  // Com numeros, o comparador e obrigatorio.
  return [...valores].sort((a, b) => b - a)
}

