challenges.solution:
function acrescentar(linhas, pedido) {
  linhas.push(`${pedido.id};${pedido.total}`)
}

function gerarRelatorio(pedidos) {
  // O acumulador nasce e morre dentro da chamada: nada sobrevive para a proxima.
  const linhas = []
  for (const pedido of pedidos) acrescentar(linhas, pedido)
  return linhas
}

