challenges.solution:
const PADRAO = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/g

function emailValido(email) {
  // Com a flag g, `test` guarda onde parou em lastIndex e a proxima chamada
  // comeca dali — por isso a mesma entrada alterna. Zerar antes de usar torna
  // a funcao independente da chamada anterior.
  PADRAO.lastIndex = 0
  return PADRAO.test(String(email).toLowerCase())
}

